// Лаба 2, п.2.2 — Function node. Автор: Korol, группа ИИ-241
const raw = Number(msg.payload);              // inject передал число 241

const digits = String(raw).split("");         // массив цифр
let sum = 0;                                  // let
const collected = [];                         // const

for (let i = 0; i < digits.length; i++) {     // цикл for
  const d = Number(digits[i]);
  collected.push(d);
  sum += d;
}

const meta = { author: "Korol", group: "ИИ-241" };   // объект

let parity = "";                              // let + if/else
if (sum % 2 === 0) {
  parity = "чётная";
} else {
  parity = "нечётная";
}

msg.payload = {                               // возврат объекта с полем payload
  input: raw,
  digits: collected,
  sum: sum,
  sumParity: parity,
  meta: meta
};
return msg;
